/**
 * The entrypoint, equivalent to webapp/src/pageRender/pageRender.jsx.
 *
 * As there, the session request goes out before the app is mounted: nothing is
 * rendered yet, and the round trip is already in flight. The `?channel` query
 * parameter is read here too, for the same reason — the channel it names is the
 * one the socket should join, not one it should switch to a moment later.
 */
import { mount } from 'svelte';

import { setChannelByName } from '$lib/state/chat.svelte';
import { initSession } from '$lib/state/session.svelte';

// generated by `npm run smui-theme` from src/theme/_smui-theme.scss
import '../theme/smui.css';
import '../theme/base.css';
import './appLayout.css';

import App from './App.svelte';

// not awaited: the app renders its loading state and fills in when this
// resolves, exactly as the react one does
void initSession();

// ?channel=ch2 — an unknown name is ignored, and the default channel stands
const urlChannel = new URLSearchParams(window.location.search).get('channel');
if (urlChannel) setChannelByName(urlChannel);

const target = document.getElementById('root');
if (!target) throw new Error('#root is missing from index.html');

export default mount(App, { target });
